func defaultTimeout(d, fallback time.Duration) time.Duration {
	if d == 0 {
		return fallback
	}
	return d
}

// RunStopJob submits a long-running job, waits for it to reach Running,
// sends a Stop (SIGTERM) control operation, and verifies the resulting
// terminal status and exit code.
func RunStopJob(t *testing.T, p launcher.Plugin, user string, opts StopOpts) {
	t.Helper()
	timeout := defaultTimeout(opts.Timeout, 30*time.Second)

	id := SubmitJob(t, p, user, opts.Job)

	// Wait for Running.
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()
	_, err := WaitForStatus(ctx, p, user, id, api.StatusRunning)
	if err != nil {
		t.Fatalf("job did not reach Running: %v", err)
	}

	// Open status stream so we can observe the transition (mirrors product behavior).
	streamCtx, streamCancel := context.WithCancel(context.Background())
	defer streamCancel()
	_, streamDone := CollectStatusStream(streamCtx, p, user)
	defer func() {
		streamCancel()
		<-streamDone
	}()

	// Give stream time to attach.
	time.Sleep(50 * time.Millisecond)

	// Send Stop.
	result, apiErr := ControlJob(p, user, id, api.OperationStop)
	if apiErr != nil {
		t.Fatalf("ControlJob(Stop) returned error: %v", apiErr)
	}
	if result != nil && !result.Complete {
		t.Log("ControlJob(Stop) returned incomplete result")
	}

	// Wait for terminal status.
	ctx2, cancel2 := context.WithTimeout(context.Background(), timeout)
	defer cancel2()
	finalJob, err := WaitForTerminalStatus(ctx2, p, user, id)
	if err != nil {
		t.Fatalf("job did not reach terminal status after Stop: %v", err)
	}

	if finalJob.Status != opts.ExpectStatus {
		t.Errorf("expected terminal status %q after Stop, got %q",
			opts.ExpectStatus, finalJob.Status)
	}

	assertExitCode(t, finalJob, opts.ExpectExitCodes)
}

// RunKillJob submits a long-running job, waits for it to reach Running,
// sends a Kill (SIGKILL) control operation, and verifies the resulting
// terminal status and exit code.
func RunKillJob(t *testing.T, p launcher.Plugin, user string, opts KillOpts) {
	t.Helper()
	timeout := defaultTimeout(opts.Timeout, 30*time.Second)

	id := SubmitJob(t, p, user, opts.Job)

	// Wait for Running.
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()
	_, err := WaitForStatus(ctx, p, user, id, api.StatusRunning)
	if err != nil {
		t.Fatalf("job did not reach Running: %v", err)
	}

	// Send Kill.
	result, apiErr := ControlJob(p, user, id, api.OperationKill)
	if apiErr != nil {
		t.Fatalf("ControlJob(Kill) returned error: %v", apiErr)
	}
	if result != nil && !result.Complete {
		t.Log("ControlJob(Kill) returned incomplete result")
	}

	// Wait for terminal status.
	ctx2, cancel2 := context.WithTimeout(context.Background(), timeout)
	defer cancel2()
	finalJob, err := WaitForTerminalStatus(ctx2, p, user, id)
	if err != nil {
		t.Fatalf("job did not reach terminal status after Kill: %v", err)
	}

	if finalJob.Status != opts.ExpectStatus {
		t.Errorf("expected terminal status %q after Kill, got %q",
			opts.ExpectStatus, finalJob.Status)

// before it starts running. Verifies the job reaches Canceled status.
//
// If the job transitions to Running before the cancel can be sent, the
// test is skipped rather than failed, since this is a known race condition
// that depends on scheduler timing.
func RunCancelJob(t *testing.T, p launcher.Plugin, user string, opts CancelOpts) {
	t.Helper()
	timeout := defaultTimeout(opts.Timeout, 30*time.Second)

	id := SubmitJob(t, p, user, opts.Job)

	// Immediately attempt to cancel.
	_, apiErr := ControlJob(p, user, id, api.OperationCancel)
	if apiErr != nil {
		// If the job already started, Cancel is invalid — this is
		// acceptable, not a test failure.
		t.Skipf("Cancel returned error (job may have started): %v", apiErr)
	}

	// Wait for Canceled status.
	ctx, cancel := context.WithTimeout(context.Background(), timeout)
	defer cancel()
	finalJob, err := WaitForStatus(ctx, p, user, id, api.StatusCanceled)
	if err != nil {
		t.Fatalf("job did not reach Canceled status: %v", err)
	}

	plugintest.AssertJobStatus(t, finalJob, api.StatusCanceled)
}

// RunSuspendResume submits a long-running job, waits for Running, suspends

// assertExitCode checks that the job's exit code is in the list of
// acceptable values.
func assertExitCode(t *testing.T, job *api.Job, acceptable []int) {
	t.Helper()
	if len(acceptable) == 0 {
		return
	}
	if job.ExitCode == nil {
		t.Error("expected exit code, but job has nil ExitCode")
		return
	}
	for _, code := range acceptable {
		if *job.ExitCode == code {
			return
		}
	}
	t.Errorf("expected exit code in %v, got %d", acceptable, *job.ExitCode)
}

def request(cls, verb, path, session=None, format_="auto", **kwargs):
    """Send an HTTP request with a session.

    Parameters
    ----------
    verb : str
        A valid HTTP request verb.
    path : str
        Path portion of URL to request.  Assumed to be relative to
        `_SERVICE_ROOT`.
    session : Session, optional
        Defaults to `current_session()`.
    format_ : {'auto', 'response', 'content', 'json', 'text'}
        The format of the return response.  Defaults to `auto`.
        response: the raw `Response` object.
        content: Response.content
        json: Response.json()
        text: Response.text
        auto: `RestObj` constructed from JSON if possible, otherwise same as
              `text`.
    **kwargs
        Additional arguments are passed to the session `request` method.

    Returns
    -------

    """
    if path.startswith("/"):
        path = cls._SERVICE_ROOT + path
    else:
        path = cls._SERVICE_ROOT + "/" + path

    return core.request(verb, path, session, format_, **kwargs)

@classmethod
def get(cls, *args, **kwargs):
    """Send a GET request."""
    try:
        return cls.request("get", *args, **kwargs)
    except HTTPError as e:
        if e.code == 404:
            return None  # Resource not found
        raise e

@classmethod

run_response = self.runs_start(
    command, is_direct, commit_id, title, tier, publish_api_endpoint
)
run_id = run_response["runId"]

poll_start = time.time()
current_retry_count = 0
while True:
    try:
        run_info = self.get_run_info(run_id)
        if run_info is None:
            raise exceptions.RunNotFoundException(
                f"Tried to access nonexistent run id {run_id}"
            )
        current_retry_count = 0
    except (
        requests.exceptions.RequestException,
        exceptions.RunNotFoundException,
    ) as e:
        current_retry_count += 1
        self.log.warning(f"Failed to get run info for runId: {run_id} : {e}")
        if current_retry_count > retry_count:
            raise Exception(
                f"Cannot get run info, max retry {retry_count} exceeded"
            ) from None
        else:
            self.log.info(
                f"Retrying ({current_retry_count}/{retry_count}) getting run info ..."
            )
            time.sleep(poll_freq)
            continue

    elapsed_time = time.time() - poll_start

    if elapsed_time >= max_poll_time:
        raise Exception(f"Run exceeded maximum time of {max_poll_time} seconds")

    output_commit_id = run_info.get("outputCommitId")
    if not output_commit_id:
        time.sleep(poll_freq)
        continue

    # once task has finished running check to see if it was successful
    else:
        stdout_msg = self.get_run_log(run_id=run_id, include_setup_log=False)

        if run_info["status"] != "Succeeded":
            self.process_log(stdout_msg)
            raise exceptions.RunFailedException(
                f"Remote run {run_id} finished but did not succeed."
            )

        break

return run_response

def run_workflow_definition(cls, name, prompts=None):
    """Runs specific Workflow Processes Definitions.

    Parameters
    ----------
    name : str
        Name or ID of an enabled workflow to execute
    prompts : dict, optional
        Input values to provide for the initial workflow prompts.  Should be
        specified as name:value pairs.

    Returns
    -------
    RestObj
        The executing workflow

    """
    workflow = cls._find_specific_workflow(name)
    if workflow is None:
        raise ValueError("No Workflow enabled for %s name or id." % name)

    if prompts is None:
        return cls.post(
            "/processes?definitionId=" + workflow["id"],
            headers={"Content-Type": "application/vnd.sas.workflow.variables+json"},
        )
    if isinstance(prompts, dict):
        variables = []

        # For each prompt defined in the workflow, check if a value was provided.
        for prompt in workflow.prompts:
            if prompt["variableName"] in prompts:
                name = prompt["variableName"]
                value = prompts[name]

                if type(value) == datetime.datetime:
                    # NOTE: do not use isinstance() to compare types as
                    # datetime.date will also evaluate as True.

                    # Explicitly convert to local time zone if not set.
                    if value.tzinfo is None:
                        try:
                            value = value.astimezone()
                        except OSError:
                            # On Windows pre-1970 dates will cause an issue.
                            # See https://bugs.python.org/issue36759
                            pass

                    if value.tzinfo is None:
                        # Failed to convert to local time.  Have to just assume it's UTC.
                        # Example: 2023-01-25T13:49:40.726162Z
                        value = value.isoformat() + "Z"
                    else:
                        # Example: 2023-01-25T13:49:40.726162-05:00
                        value = value.isoformat()

                variables.append(
                    {
                        "name": name,
                        "value": value,
                        "scope": "local",
                        "type": prompt["variableType"],
                        "version": prompt["version"],
                    }
                )

        return cls.post(
            "/processes?definitionId=" + workflow["id"],
            json={"variables": variables},
            headers={"Content-Type": "application/vnd.sas.workflow.variables+json"},

