private void emit(String eventAsJson) {
  log.debug("POST event on URL {}", uri);
  try {
    ClassicRequestBuilder request = ClassicRequestBuilder.post(uri);
    setHeaders(request);
    setBody(request, eventAsJson);

    http.execute(
        request.build(),
        response -> {
          throwOnHttpError(response);
          return null;
        });
  } catch (IOException e) {
    throw new OpenLineageClientException(e);
  }
}

private void setBody(ClassicRequestBuilder request, String body) {
  HttpEntity entity = new StringEntity(body, APPLICATION_JSON);
  if (compression == HttpConfig.Compression.GZIP) {
    entity = new GzipCompressingEntity(entity);
  }
  request.setEntity(entity);
}

private void setHeaders(ClassicRequestBuilder request) {
  this.headers.forEach((key, value) -> request.setHeader(key, value));
  // set headers to accept json
  request.setHeader(ACCEPT, APPLICATION_JSON.toString());
  request.setHeader(CONTENT_TYPE, APPLICATION_JSON.toString());
  // if tokenProvider preset overwrite authorization
  if (tokenProvider != null) {
    request.addHeader(AUTHORIZATION, tokenProvider.getToken());
  }
  if (compression != null) {
    request.addHeader(CONTENT_ENCODING, compression.getContentEncoding());
  }
}

private void throwOnHttpError(@NonNull ClassicHttpResponse response)
    throws IOException, ParseException {
  final int code = response.getCode();
  HttpEntity entity = response.getEntity();
  String body = EntityUtils.toString(entity, UTF_8);
  EntityUtils.consume(entity);
  if (code >= 400 && code < 600) { // non-2xx
    throw new HttpTransportResponseException(code, body);
  }
}

@Override
public void close() throws IOException {
  http.close();
}

def filter_event(
    self,
    event: Event,
) -> Event | None:
    """Filters jobs according to config-defined events"""
    for _filter in self._filters:
        if isinstance(event, (RunEvent, event_v2.RunEvent)) and _filter.filter_event(event) is None:
            return None
    return event

def emit(self, event: Event) -> None:
    from typing import get_args

    if type(event) not in get_args(Event):
        msg = "`emit` only accepts RunEvent, DatasetEvent, JobEvent classes"
        raise ValueError(msg)

    event = self.add_environment_facets(event)
    event = self.update_event_tags_facets(event)
    event = self.add_source_code_location_facet(event)
    if self.config.dataset.reducing_enabled:
        # Reduce datasets to their canonical form (e.g. "/data/events" instead of
        # "/data/events/dt=2025-09-01"). All subsequent processing (e.g. event filtering)
        # will work on these modified values.
        event = self.reduce_datasets(event)

    if log.isEnabledFor(logging.DEBUG):
        val = Serde.to_json(event).encode("utf-8")
        log.debug("OpenLineageClient will *try* to emit event %s", val)

    if not self.transport:
        log.error("Tried to emit OpenLineage event, but transport is not configured.")
        return
    if self.transport.kind == NoopTransport.kind:
        log.debug("OpenLineage is disabled. No events will be emitted.")
        return
    if self._filters and self.filter_event(event) is None:
        log.debug("OpenLineage event has been filtered out and will not be emitted.")
        return

    self.transport.emit(event)
    log.debug("OpenLineage event successfully emitted.")

def close(self, timeout: float = -1.0) -> bool:
    """
    Closes down the transport until all events are processed or timeout is reached.
    Params:
      timeout: Timeout in seconds. `-1` means to block until last event is processed, 0 means no timeout.

    """
    return self.transport.close(timeout)

def get_session() -> Session:
    from requests import Session

    return Session()


@attr.define
class HttpConfig(Config):
    url: str
    endpoint: str = "api/v1/lineage"
    timeout: float = 5.0
    # check TLS certificates
    verify: bool = True
    auth: TokenProvider = attr.field(factory=lambda: TokenProvider({}))
    compression: HttpCompression | None = None
    # not set by TransportFactory
    session: Session | None = None
    # not set by TransportFactory
    adapter: HTTPAdapter | None = None
    # custom headers support
    custom_headers: dict[str, str] = attr.field(factory=dict)
    # retry settings
    retry: dict[str, Any] = attr.field(default=DEFAULT_RETRY_CONFIG)

    @classmethod
    def from_dict(cls, params: dict[str, Any]) -> HttpConfig:
        if "url" not in params:
            msg = "`url` key not passed to HttpConfig"
            raise RuntimeError(msg)
        specified_dict = get_only_specified_fields(cls, params)
        specified_dict["auth"] = create_token_provider(specified_dict.get("auth", {}))
        compression = specified_dict.get("compression")
        if compression:
            specified_dict["compression"] = HttpCompression(compression)

        # Merge retry config with defaults to preserve unspecified values
        if "retry" in specified_dict:
            specified_dict["retry"] = {**DEFAULT_RETRY_CONFIG, **specified_dict["retry"]}

        return cls(**specified_dict)

    self.timeout = config.timeout
    self.verify = config.verify
    self.compression = config.compression
    self._session: Session | None = None
    self.session = config.session

def emit(self, event: Event) -> Response:
    # If anyone overrides debuglevel manually, we can potentially leak secrets to logs.
    # Override this setting to make sure it does not happen.
    prev_debuglevel = http_client.HTTPConnection.debuglevel
    http_client.HTTPConnection.debuglevel = 0
    try:
        body, headers = self._prepare_request(Serde.to_json(event))

        resp = self.session.post(
            url=urljoin(self.url, self.endpoint),
            data=body,
            headers=headers,
            timeout=self.timeout,
            verify=self.verify,
        )
        resp.close()
        resp.raise_for_status()
        return resp
    finally:
        http_client.HTTPConnection.debuglevel = prev_debuglevel

@property
def session(self) -> Session:
    if not self._session:
        self._session = Session()
        self._prepare_session(self._session)
    return self._session

@session.setter
def session(self, value: Session | None) -> None:
    if value:
        self._prepare_session(value)
    self._session = value

def close(self, timeout: float = -1) -> bool:
    if self._session:
        self._session.close()
        self._session = None
    return True

def _auth_headers(self, token_provider: TokenProvider) -> dict:  # type: ignore[type-arg]
    bearer = token_provider.get_bearer()
    if bearer:
        return {"Authorization": bearer}
    return {}

def _prepare_session(self, session: Session) -> None:
    if self.config.adapter:
        session.mount(self.url, self.config.adapter)
    else:
        session.mount(self.url, self._prepare_adapter())

def _prepare_adapter(self) -> HTTPAdapter:
    retry = urllib3.util.Retry(**self.config.retry)
    return HTTPAdapter(max_retries=retry)

def _prepare_request(self, event_str: str) -> tuple[bytes | str, dict[str, str]]:
    headers = {
        "Content-Type": "application/json",
        **self._auth_headers(self.config.auth),
        **self.config.custom_headers,
    }
    if self.compression == HttpCompression.GZIP:
        headers["Content-Encoding"] = "gzip"
        # levels higher than 3 are twice as slow:
        # https://github.com/python/cpython/issues/91349#issuecomment-2737161048
        return gzip.compress(event_str.encode("utf-8"), compresslevel=3), headers

    return event_str, headers

